                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.online_channel_metrics as with as_of as ( select current_date() as as_of_date ), params as ( select a.as_of_date, a.as_of_date - 7 as d7, a.as_of_date - 15 as d15, a.as_of_date - 30 as d30, a.as_of_date - 60 as d60, a.as_of_date - 90 as d90, date_trunc(\'month\', a.as_of_date)::date as mtd_start from as_of a ), base_inv as ( select date as inv_date, trim( upper( reverse( substring( reverse(\"Item SkuCode\"), charindex(\'-\', reverse(\"Item SkuCode\")) + 1, len(\"Item SkuCode\") ) ) ) ) as sku_group, sum(inventory) as inv from snitch_db.maplemonk.snitch_final_inventory_wh2 cross join params p where facility in ( \'SAPL-WH2\', \'SAPL-WH1\', \'SAPL_EMIZA\', \'SAPL-NORTH-TAURU\' ) and date >= p.as_of_date - 91 group by 1, 2 ) , inv_summary as (select b.sku_group, t.l1_category, t.category, sum(case when b.inv_date = p.as_of_date then b.inv else 0 end) as current_inv, sum(case when b.inv_date = p.d7 then b.inv else 0 end) as p7d_inv, sum(case when b.inv_date = p.d15 then b.inv else 0 end) as p15d_inv, sum(case when b.inv_date = p.d30 then b.inv else 0 end) as p30d_inv, sum(case when b.inv_date = p.d60 then b.inv else 0 end) as p60d_inv, sum(case when b.inv_date = p.d90 then b.inv else 0 end) as p90d_inv from base_inv b left join snitch_db.maplemonk.temp_table_cogs t using (sku_group) cross join params p group by 1, 2, 3 ) , putaway_raw as ( select upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) as sku_group, \"PUTAWAY_UPDATED\"::date as putaway_date, lower(final_type) as final_type, sum(\"PUTAWAY_COMPLETED_QUANTITY\") as qty from snitch_db.maplemonk.putaway_tracking where \"PUTAWAY_UPDATED\" >= date \'2025-11-01\' and lower(final_type) in (\'new inward\', \'b2c return inward\') group by 1, 2, 3 ), inwarded as ( select ff.sku_group, case WHEN LOWER(ff.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(ff.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end as l1_category, lower( replace( ifnull( a.category,case WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' when upper(ff.sku_group) like \'4MSN%\' THEN \'Shirts\' when upper(ff.sku_group) like \'4MCR1004%\' then \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MCSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MTR0123%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSWHC%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWC%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MSKC%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MCRD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MCRT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MTLX%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MLRT%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(ff.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSW%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(ff.sku_group) LIKE \'4MST%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(ff.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'Belts\' WHEN UPPER(ff.sku_group) LIKE \'4MLX%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MPL%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'Accessories\' end ), \'-\', \'\' ) ) as category, ff.putaway_date, ff.final_type, ff.qty, ff.qty * cost_price as inward_value from putaway_raw ff left join snitch_db.maplemonk.temp_table_cogs b on ff.sku_group = b.sku_group left join snitch_db.maplemonk.metafields_data a on ff.sku_group = a.sku_group ), inward_summary as ( select i.sku_group, i.l1_category, i.category, sum( case when i.final_type = \'new inward\' and i.putaway_date >= p.as_of_date - 30 then i.qty else 0 end ) as new_inward_l30d, sum( case when i.final_type = \'new inward\' and i.putaway_date >= p.as_of_date - 60 then i.qty else 0 end ) as new_inward_l60d, sum( case when i.final_type = \'b2c return inward\' and i.putaway_date >= p.as_of_date - 30 then i.qty else 0 end ) as b2c_return_inward_l30d, sum( case when i.final_type = \'b2c return inward\' and i.putaway_date >= p.as_of_date - 60 then i.qty else 0 end ) as b2c_return_inward_l60d from inwarded i cross join params p group by 1, 2, 3 ) , base_sales as ( select s.date as sales_date, s.sku_group, s.gross_quantity::int as sales_qty, s.gross_sales::number(38, 2) as sales_value, s.discount_amount::number(38, 2) as sales_discount, case when s.gross_quantity is null or s.gross_quantity = 0 then 0 when s.gross_sales / nullif(s.gross_quantity, 0) < 999 then s.gross_sales * 0.05 else s.gross_sales * 0.12 end as sales_tax from snitch_db.maplemonk.horizontal_sales_categories s cross join params p where lower(s.type) = \'shopify\' and s.date >= p.as_of_date - 90 and s.date <= p.as_of_date ), sales_summary_base as ( select s.sku_group, t.l1_category, t.category, sum(case when s.sales_date >= p.as_of_date - 30 then s.sales_qty else 0 end) as sales_qty_l30d, sum(case when s.sales_date >= p.as_of_date - 30 then s.sales_value else 0 end) as sales_value_l30d, sum(case when s.sales_date >= p.as_of_date - 30 then s.sales_discount else 0 end) as sales_discount_l30d, sum(case when s.sales_date >= p.as_of_date - 30 then s.sales_tax else 0 end) as sales_tax_l30d, sum(case when s.sales_date >= p.as_of_date - 30 then s.sales_qty * t.cost_price else 0 end) as sales_cogs_l30d, sum(case when s.sales_date >= p.mtd_start then s.sales_qty else 0 end) as sales_qty_mtd, sum(case when s.sales_date >= p.mtd_start then s.sales_value else 0 end) as sales_value_mtd, sum(case when s.sales_date >= p.mtd_start then s.sales_discount else 0 end) as sales_discount_mtd, sum(case when s.sales_date >= p.mtd_start then s.sales_tax else 0 end) as sales_tax_mtd, sum(case when s.sales_date >= p.mtd_start then s.sales_qty * t.cost_price else 0 end) as sales_cogs_mtd, sum(case when s.sales_date >= p.as_of_date - 60 then s.sales_qty else 0 end) as sales_qty_l60d, sum(case when s.sales_date >= p.as_of_date - 60 then s.sales_value else 0 end) as sales_value_l60d, sum(case when s.sales_date >= p.as_of_date - 60 then s.sales_discount else 0 end) as sales_discount_l60d, sum(case when s.sales_date >= p.as_of_date - 60 then s.sales_tax else 0 end) as sales_tax_l60d, sum(case when s.sales_date >= p.as_of_date - 60 then s.sales_qty * t.cost_price else 0 end) as sales_cogs_l60d, sum(case when s.sales_date >= p.as_of_date - 90 then s.sales_qty else 0 end) as sales_qty_l90d, sum(case when s.sales_date >= p.as_of_date - 90 then s.sales_value else 0 end) as sales_value_l90d, sum(case when s.sales_date >= p.as_of_date - 90 then s.sales_discount else 0 end) as sales_discount_l90d, sum(case when s.sales_date >= p.as_of_date - 90 then s.sales_tax else 0 end) as sales_tax_l90d, sum(case when s.sales_date >= p.as_of_date - 90 then s.sales_qty * t.cost_price else 0 end) as sales_cogs_l90d from base_sales s left join snitch_db.maplemonk.temp_table_cogs t using (sku_group) cross join params p group by 1, 2, 3 ), sales_summary as ( select s.sku_group, s.l1_category, s.category, s.sales_qty_l30d, s.sales_value_l30d, s.sales_qty_mtd, s.sales_value_mtd, s.sales_qty_l60d, s.sales_value_l60d, s.sales_qty_l90d, s.sales_value_l90d, s.sales_discount_l30d , s.sales_discount_mtd , s.sales_discount_l60d , s.sales_discount_l90d , s.sales_tax_l30d , s.sales_cogs_l30d, s.sales_tax_mtd , s.sales_cogs_mtd, s.sales_tax_l60d , s.sales_cogs_l60d, s.sales_tax_l90d , s.sales_cogs_l90d, from sales_summary_base s ), product_journey as ( select upper(trim(sku_group::varchar)) as sku_group, status, final_live_date::date as final_live_date from snitch_db.maplemonk.product_journey ), design_flags as ( select pj.sku_group, case when pj.status = \'draft\' or pj.final_live_date is null then 0 else 1 end as designs_live, case when pj.status <> \'draft\' and pj.final_live_date is not null and pj.final_live_date >= p.as_of_date - 30 then 1 else 0 end as new_designs_l30d, case when pj.status = \'draft\' or pj.final_live_date is null then \'not_live\' when greatest(0, datediff(\'day\', pj.final_live_date, p.as_of_date)) <= 30 then \'0-30\' when greatest(0, datediff(\'day\', pj.final_live_date, p.as_of_date)) <= 90 then \'30-90\' when greatest(0, datediff(\'day\', pj.final_live_date, p.as_of_date)) <= 180 then \'90-180\' when greatest(0, datediff(\'day\', pj.final_live_date, p.as_of_date)) <= 270 then \'180-270\' when greatest(0, datediff(\'day\', pj.final_live_date, p.as_of_date)) <= 360 then \'270-360\' else \'360+\' end as ageing_bucket from product_journey pj cross join params p ), sales_flags as ( select s.sku_group, case when sum(case when s.sales_date >= p.as_of_date - 30 then s.sales_qty else 0 end) > 0 then 1 else 0 end as designs_sold_l30d, case when sum(case when s.sales_date >= p.as_of_date - 60 then s.sales_qty else 0 end) > 0 then 1 else 0 end as designs_sold_l60d, case when sum(case when s.sales_date >= p.as_of_date - 15 then s.sales_qty else 0 end) > 0 then 1 else 0 end as designs_sold_l15d, case when sum(case when s.sales_date >= p.as_of_date - 7 then s.sales_qty else 0 end) > 0 then 1 else 0 end as designs_sold_l7d from base_sales s cross join params p group by 1 ), inv_current_by_sku as ( select sku_group, coalesce(sum(current_inv), 0) as inv_current from inv_summary group by 1 ), inward_lots as ( select upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) as sku_group, \"PUTAWAY_UPDATED\"::date as inward_date, sum(\"PUTAWAY_COMPLETED_QUANTITY\") as inward_qty from snitch_db.maplemonk.putaway_tracking where lower(final_type) in (\'new inward\') group by 1, 2 ), inward_lots_fifo as ( select il.sku_group, il.inward_date, il.inward_qty, sum(il.inward_qty) over ( partition by il.sku_group order by il.inward_date asc rows between unbounded preceding and current row ) as cum_inward_qty, sum(il.inward_qty) over ( partition by il.sku_group order by il.inward_date asc rows between unbounded preceding and current row ) - il.inward_qty as cum_inward_qty_prev from inward_lots il ), inward_total as ( select sku_group, sum(inward_qty) as total_inward_qty from inward_lots group by 1 ), fifo_remaining_by_lot as ( select x.sku_group, x.inward_date, x.inward_qty, x.inv_current, x.total_inward_qty, x.consumed_qty, greatest( least(x.inward_qty, x.consumed_qty - x.cum_inward_qty_prev), 0 ) as consumed_in_this_lot, greatest( x.inward_qty - greatest( least(x.inward_qty, x.consumed_qty - x.cum_inward_qty_prev), 0 ), 0 ) as remaining_qty, greatest(datediff(\'day\', x.inward_date, x.as_of_date), 0) as lot_age_days from ( select f.sku_group, f.inward_date, f.inward_qty, f.cum_inward_qty_prev, coalesce(ic.inv_current, 0) as inv_current, coalesce(it.total_inward_qty, 0) as total_inward_qty, greatest(coalesce(it.total_inward_qty, 0) - coalesce(ic.inv_current, 0), 0) as consumed_qty, a.as_of_date from inward_lots_fifo f left join inv_current_by_sku ic using (sku_group) left join inward_total it using (sku_group) cross join as_of a ) x ), fifo_sku_base as ( select sku_group from inv_current_by_sku union select sku_group from inward_total ), inv_ageing_fifo as ( select b.sku_group, coalesce(max(ic.inv_current), 0) as inv_current, coalesce(sum(fr.remaining_qty), 0) as remaining_qty_total, case when coalesce(max(ic.inv_current), 0) = 0 then 0 when coalesce(sum(fr.remaining_qty), 0) = 0 then 0 else coalesce(sum(fr.remaining_qty * fr.lot_age_days), 0) / nullif(coalesce(sum(fr.remaining_qty), 0), 0) end as weighted_age_days, min(case when fr.remaining_qty > 0 then fr.inward_date end) as oldest_inward_date_in_stock, max(case when fr.remaining_qty > 0 then fr.inward_date end) as newest_inward_date_in_stock from fifo_sku_base b left join inv_current_by_sku ic using (sku_group) left join fifo_remaining_by_lot fr using (sku_group) group by 1 ), clicks as ( select upper(trim(sku_group)) as sku_group, sum(case when datediff(day, ga_date, current_date) <= 8 then ifnull(clicks::int, 0) end)::int as clicks7, sum(case when datediff(day, ga_date, current_date) <= 31 then ifnull(clicks::int, 0) end)::int as clicks30 from snitch_db.maplemonk.clicks_itemid group by 1 ), offline_allocated as ( select upper(trim(regexp_replace(sku, \'-[^-]+$\', \'\'))) as sku_group, sum(case when order_date >= p.as_of_date - 30 then qty else 0 end) as offline_allocated_l30d from snitch_db.maplemonk.b2b_journey cross join params p group by 1 ) select coalesce(inv.sku_group, inw.sku_group, s.sku_group, d.sku_group, sf.sku_group, c.sku_group, oa.sku_group, fifo.sku_group) as sku_group, coalesce(inv.l1_category, inw.l1_category, s.l1_category) as l1_category, coalesce(inv.category, inw.category, s.category) as category, coalesce(inv.current_inv, 0) as current_inv, coalesce(inv.p7d_inv, 0) as p7d_inv, coalesce(inv.p15d_inv, 0) as p15d_inv, coalesce(inv.p30d_inv, 0) as p30d_inv, coalesce(inv.p60d_inv, 0) as p60d_inv, coalesce(inv.p90d_inv, 0) as p90d_inv, coalesce(oa.offline_allocated_l30d, 0) as offline_allocated_l30d, coalesce(inw.new_inward_l30d, 0) as new_inward_l30d, coalesce(inw.new_inward_l60d, 0) as new_inward_l60d, coalesce(inw.b2c_return_inward_l30d, 0) as b2c_return_inward_l30d, coalesce(inw.b2c_return_inward_l60d, 0) as b2c_return_inward_l60d, coalesce(s.sales_qty_l30d, 0) as sales_qty_l30d, coalesce(s.sales_value_l30d, 0) as sales_value_l30d, coalesce(s.sales_qty_mtd, 0) as sales_qty_mtd, coalesce(s.sales_value_mtd, 0) as sales_value_mtd, coalesce(s.sales_qty_l60d, 0) as sales_qty_l60d, coalesce(s.sales_value_l60d, 0) as sales_value_l60d, coalesce(s.sales_qty_l90d, 0) as sales_qty_l90d, coalesce(s.sales_value_l90d, 0) as sales_value_l90d, coalesce(s.sales_discount_l30d, 0) as discount_pct_l30d, coalesce(s.sales_discount_mtd, 0) as sales_discount_mtd, coalesce(s.sales_discount_l60d, 0) as sales_discount_l60d, coalesce(s.sales_discount_l90d, 0) as sales_discount_l90d, coalesce(s.sales_tax_l30d, 0) as sales_tax_l30d, coalesce(s.sales_tax_mtd, 0) as sales_tax_mtd, coalesce(s.sales_tax_l60d, 0) as sales_tax_l60d, coalesce(s.sales_tax_l90d, 0) as sales_tax_l90d, coalesce(s.sales_cogs_l30d, 0) as sales_cogs_l30d, coalesce(s.sales_cogs_mtd, 0) as sales_cogs_mtd, coalesce(s.sales_cogs_l60d, 0) as sales_cogs_l60d, coalesce(s.sales_cogs_l90d, 0) as sales_cogs_l90d, coalesce(c.clicks7, 0) as clicks7, coalesce(c.clicks30, 0) as clicks30, coalesce(d.ageing_bucket, \'not_live\') as ageing_bucket, coalesce(d.new_designs_l30d, 0) as new_designs_l30d, coalesce(d.designs_live, 0) as designs_live, coalesce(sf.designs_sold_l30d, 0) as designs_sold_l30d, coalesce(sf.designs_sold_l60d, 0) as designs_sold_l60d, coalesce(sf.designs_sold_l15d, 0) as designs_sold_l15d, coalesce(sf.designs_sold_l7d, 0) as designs_sold_l7d, coalesce(fifo.weighted_age_days, 0) as inv_weighted_age_days_fifo, case when coalesce(fifo.weighted_age_days, 0) <= 30 then \'0-30\' when coalesce(fifo.weighted_age_days, 0) <= 90 then \'30-90\' when coalesce(fifo.weighted_age_days, 0) <= 180 then \'90-180\' when coalesce(fifo.weighted_age_days, 0) <= 270 then \'180-270\' when coalesce(fifo.weighted_age_days, 0) <= 360 then \'270-360\' else \'360+\' end as inventory_ageing_buckets from inv_summary inv full outer join inward_summary inw using (sku_group) full outer join sales_summary s using (sku_group) full outer join design_flags d using (sku_group) full outer join sales_flags sf using (sku_group) full outer join inv_ageing_fifo fifo using (sku_group) full outer join clicks c using (sku_group) full outer join offline_allocated oa using (sku_group) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

